import * as THREE from 'three';
import raw from './pfluger-bridge.json' with { type: 'json' };

/** James D. Pfluger Pedestrian & Bicycle Bridge (Lady Bird Lake, beside Lamar Blvd).
 * Plan: City of Austin impervious cover 2023 'Bridge' OBJECTID 9608; deck: smooth structural profile fitted to LiDAR
 * class 13 returns along the branch centrelines; the north double helix grade is fitted to the visible top turn
 * (pfluger-bridge.json, generated by tools/extension/bake-pfluger-bridge.py). Form (reference-guided): tinted concrete deck with dusty-red
 * edge bands, curved weathering-steel plate girders, curved twin-column concrete bents, grey rail + vertical mesh infill,
 * tall grey lamp posts with double saucer caps on square plinths, planters on the wide central plaza. No cables/towers.
 * Pure geometry (no GPU): Node checks build exactly what the game renders. */

type V3 = [number, number, number];
export interface PflugerData {
  oid: number; slab: number; band: number; waterY: number;
  helix: { c: [number, number]; rIn: number; rOut: number; phiTop: number; phiEnd: number; slope: number; yTop: number; yEnd: number };
  deck: V3[][]; centre: V3[][][]; girders: V3[][]; source: [number, number][][];
  open: { name: string; x: number; z: number; r: number; kind: 'ground' | 'helix'; ground?: number }[];
  piers: { path: string; s: number; x: number; z: number; dir: [number, number]; half: number; deck: number; base: number; water: boolean }[];
  lidar: [number, number, number, string][];
  /** Branch centrelines with the fitted deck profile (x, y, z at 1 m); absent in pre-profile data. */
  paths?: Record<string, V3[]>;
  /** Walkable deck surface on a 2.5 m grid (x, y, z flat; triangle indices; per-triangle 0 band / 1 centre). */
  mesh?: { v: number[]; t: number[]; c: number[] };
  profile?: { lambda: number; branches: Record<string, { residualRms: number; residualP95: number; maxGrade: number; maxSecondDiff: number }> };
}
export const PFLUGER = raw as unknown as PflugerData;

/** Plate girder web depth below the slab (m; estimate: ~L/27 for the 38 m longest span). */
export const GIRDER_DEPTH = 1.4;
export const RAIL_HEIGHT = 1.1;
const LAMP_SPACING = 16, POST_SPACING = 2.4, HELIX_STEP = 6;

const srgb = (hex: number) => new THREE.Color().setHex(hex, THREE.SRGBColorSpace);
export const PFLUGER_COLORS = {
  band: srgb(0x9a5a4c),       // dusty red tinted concrete bands
  centre: srgb(0xc7a68e),     // warm tan/pink concrete
  concrete: srgb(0xb8b0a3), soffit: srgb(0x8f8a82),
  steel: srgb(0x6a3a22),      // weathering steel
  rail: srgb(0x8b9297), lamp: srgb(0x9aa1a5), glass: srgb(0xf3ead0), plant: srgb(0x4e6a33), soil: srgb(0x5a4632),
};

class Soup {
  pos: number[] = []; col: number[] = [];
  get triangles() { return this.pos.length / 9; }
  tri(a: V3, b: V3, c: V3, color: THREE.Color, up = false) {
    let p = [a, b, c];
    if (up) {
      const ny = (b[2] - a[2]) * (c[0] - a[0]) - (b[0] - a[0]) * (c[2] - a[2]);
      if (ny < 0) p = [a, c, b];
    }
    for (const q of p) { this.pos.push(q[0], q[1], q[2]); this.col.push(color.r, color.g, color.b); }
  }
  quad(a: V3, b: V3, c: V3, d: V3, color: THREE.Color) { this.tri(a, b, c, color); this.tri(a, c, d, color); }
  /** Axis box in a local frame: centre, unit axes u (horizontal) and v (horizontal), half sizes, y range. */
  box(cx: number, cz: number, u: [number, number], hu: number, hv: number, y0: number, y1: number, color: THREE.Color, top = true) {
    const v: [number, number] = [-u[1], u[0]];
    const P = (su: number, sv: number, y: number): V3 => [cx + u[0] * hu * su + v[0] * hv * sv, y, cz + u[1] * hu * su + v[1] * hv * sv];
    const cs: [number, number][] = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
    for (let k = 0; k < 4; k++) { const [a, b] = [cs[k], cs[(k + 1) % 4]]; this.quad(P(a[0], a[1], y0), P(b[0], b[1], y0), P(b[0], b[1], y1), P(a[0], a[1], y1), color); }
    if (top) this.quad(P(-1, -1, y1), P(1, -1, y1), P(1, 1, y1), P(-1, 1, y1), color);
  }
  /** n-gon prism (columns, poles) or frustum disc when r0 != r1. */
  prism(cx: number, cz: number, r0: number, r1: number, y0: number, y1: number, n: number, color: THREE.Color, cap = false) {
    for (let k = 0; k < n; k++) {
      const a = k / n * Math.PI * 2, b = (k + 1) / n * Math.PI * 2;
      this.quad([cx + Math.cos(a) * r0, y0, cz + Math.sin(a) * r0], [cx + Math.cos(b) * r0, y0, cz + Math.sin(b) * r0],
        [cx + Math.cos(b) * r1, y1, cz + Math.sin(b) * r1], [cx + Math.cos(a) * r1, y1, cz + Math.sin(a) * r1], color);
      if (cap) this.tri([cx, y1, cz], [cx + Math.cos(a) * r1, y1, cz + Math.sin(a) * r1], [cx + Math.cos(b) * r1, y1, cz + Math.sin(b) * r1], color);
    }
  }
  geometry(uv?: number[]) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(this.pos), 3));
    g.setAttribute('color', new THREE.BufferAttribute(new Float32Array(this.col), 3));
    if (uv) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(uv), 2));
    g.computeVertexNormals(); g.computeBoundingBox(); g.computeBoundingSphere();
    return g;
  }
}

function inRing(x: number, z: number, ring: { 0: number; 1: number; 2?: number }[], zi: 1 | 2) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const a = ring[i], b = ring[j], az = a[zi]!, bz = b[zi]!;
    if ((az > z) !== (bz > z) && x < (b[0] - a[0]) * (z - az) / (bz - az) + a[0]) inside = !inside;
  }
  return inside;
}
function segDist(x: number, z: number, ax: number, az: number, bx: number, bz: number) {
  const dx = bx - ax, dz = bz - az, d = dx * dx + dz * dz, t = d ? Math.min(1, Math.max(0, ((x - ax) * dx + (z - az) * dz) / d)) : 0;
  return Math.hypot(ax + dx * t - x, az + dz * t - z);
}

/** Inside the City polygon (OID 9608) or within `margin` of its outline: where the baked flat soup is replaced. */
export function pflugerCovers(x: number, z: number, margin = 1.2, d: PflugerData = PFLUGER) {
  const s = d.source;
  let inside = false;
  for (const r of s) if (inRing(x, z, r, 1)) inside = !inside;
  if (inside) return true;
  for (const r of s) for (let i = 0; i < r.length; i++) {
    const a = r[i], b = r[(i + 1) % r.length];
    if (segDist(x, z, a[0], a[1], b[0], b[1]) < margin) return true;
  }
  return false;
}
/** Main deck (even-odd over its rings), excluding the helix. */
function inDeckOf(d: PflugerData, x: number, z: number) {
  let inside = false;
  for (const r of d.deck) if (inRing(x, z, r, 2)) inside = !inside;
  return inside;
}
const helixYOf = (d: PflugerData, phi: number) => d.helix.yTop + d.helix.slope * (phi - d.helix.phiTop);
const inOpenOf = (d: PflugerData, x: number, z: number, kind?: 'ground' | 'helix') => d.open.some(o => (!kind || o.kind === kind) && Math.hypot(x - o.x, z - o.z) < o.r);

/** Profile roughness of a polyline (x, y, z), resampled every 0.5 m of plan length: the steepest grade over any 1.5 m
 * window and the largest second difference of y between consecutive 1 m samples (change of grade per metre). */
export function profileRoughness(points: V3[]) {
  const s: number[] = [0];
  for (let i = 1; i < points.length; i++) s.push(s[i - 1] + Math.hypot(points[i][0] - points[i - 1][0], points[i][2] - points[i - 1][2]));
  const L = s[s.length - 1], at = (t: number) => {
    let i = 1; while (i < s.length - 1 && s[i] < t) i++;
    const u = s[i] > s[i - 1] ? (t - s[i - 1]) / (s[i] - s[i - 1]) : 0;
    return points[i - 1][1] + (points[i][1] - points[i - 1][1]) * Math.min(1, Math.max(0, u));
  };
  const y: number[] = [];
  for (let t = 0; t <= L; t += .5) y.push(at(t));
  let maxGrade = 0, maxSecondDiff = 0, gradeAt = 0;
  for (let i = 0; i + 3 < y.length; i++) { const g = Math.abs(y[i + 3] - y[i]) / 1.5; if (g > maxGrade) { maxGrade = g; gradeAt = i * .5; } }
  for (let i = 2; i + 2 < y.length; i++) maxSecondDiff = Math.max(maxSecondDiff, Math.abs(y[i + 2] - 2 * y[i] + y[i - 2]));
  return { lengthM: +L.toFixed(1), maxGrade: +maxGrade.toFixed(4), maxSecondDiff: +maxSecondDiff.toFixed(4), gradeAtM: gradeAt };
}

function triangulate(rings: V3[][], soup: Soup, color: THREE.Color, dy = 0) {
  const contour = rings[0].map(p => new THREE.Vector2(p[0], p[2]));
  const holes = rings.slice(1).map(r => r.map(p => new THREE.Vector2(p[0], p[2])));
  const all = rings.flat();
  for (const t of THREE.ShapeUtils.triangulateShape(contour, holes)) {
    const [a, b, c] = t.map(k => [all[k][0], all[k][1] + dy, all[k][2]] as V3);
    soup.tri(a, b, c, color, true); // soffits face up too: the double-sided material flips back-face normals
  }
}

export interface PflugerGeometry {
  /** Walkable deck tops (main deck + helix) and the land supports: rendered == collider. */
  deck: THREE.BufferGeometry;
  deckCollider: { position: Float32Array; index: Uint32Array };
  /** Visual: soffits, fascias, girders, water piers, posts, rails, lamps, planters. */
  structure: THREE.BufferGeometry;
  /** Vertical mesh infill panels (uv.x = metres / mesh pitch). */
  infill: THREE.BufferGeometry;
  /** Railing collider: one vertical quad per railing segment (deck - 0.2 .. deck + RAIL_HEIGHT). */
  railCollider: { position: Float32Array; index: Uint32Array };
  /** Railing top polylines along the main deck edges (runs between open landings). */
  railTops: V3[][];
  stats: { deckTriangles: number; structureTriangles: number; infillTriangles: number; railSegments: number; railLengthM: number; lamps: number; planters: number;
    piers: number; helixColumns: number; girderLengthM: number; helixTurns: number };
}

/** Railing polyline sample: point + deck height + unit inward normal. */
interface RailSeg { a: V3; b: V3 }

export function buildPflugerGeometry(D: PflugerData = PFLUGER): PflugerGeometry {
  const inDeck = (x: number, z: number) => inDeckOf(D, x, z), helixY = (phi: number) => helixYOf(D, phi);
  const inOpen = (x: number, z: number, kind?: 'ground' | 'helix') => inOpenOf(D, x, z, kind);
  const railTops: V3[][] = [];
  const C = PFLUGER_COLORS, H = D.helix, slab = D.slab;
  const deck = new Soup(), st = new Soup(), mesh = new Soup(), meshUv: number[] = [];
  const rails: RailSeg[] = [];

  // ---- main deck: dusty-red edge band + tan centre. Generated data carries a gridded surface mesh that follows the
  // smooth profile; older data (rings only) falls back to triangulating the rings.
  if (D.mesh) {
    const { v, t, c } = D.mesh, P = (k: number, dy = 0): V3 => [v[k * 3], v[k * 3 + 1] + dy, v[k * 3 + 2]];
    for (let i = 0; i < c.length; i++) {
      deck.tri(P(t[i * 3]), P(t[i * 3 + 1]), P(t[i * 3 + 2]), c[i] ? C.centre : C.band, true);
      st.tri(P(t[i * 3], -slab), P(t[i * 3 + 1], -slab), P(t[i * 3 + 2], -slab), C.soffit, true);
    }
  } else {
    const centreExt = D.centre.map(p => p[0]);
    const bandHoles: V3[][] = [...centreExt];
    const annuli: V3[][][] = [];
    for (const h of D.deck.slice(1)) {
      const [x, , z] = h[0];
      const part = D.centre.find(p => inRing(x, z, p[0], 2));
      const ch = part?.slice(1).find(r => inRing(x, z, r, 2));
      if (ch) annuli.push([ch, h]); else if (!part) bandHoles.push(h);
    }
    triangulate([D.deck[0], ...bandHoles], deck, C.band);
    for (const a of annuli) triangulate(a, deck, C.band);
    for (const p of D.centre) triangulate([p[0], ...p.slice(1).filter(r => !annuli.some(a => a[0] === r))], deck, C.centre);
    triangulate(D.deck, st, C.soffit, -slab);
  }
  // fascia, railings, abutments
  for (const r of D.deck) for (let i = 0, run: V3[] | null = null; i < r.length; i++) {
    const a = r[i], b = r[(i + 1) % r.length];
    st.quad([a[0], a[1] + .04, a[2]], [b[0], b[1] + .04, b[2]], [b[0], b[1] - slab - .25, b[2]], [a[0], a[1] - slab - .25, a[2]], C.concrete);
    const mx = (a[0] + b[0]) / 2, mz = (a[2] + b[2]) / 2;
    if (!inOpen(mx, mz)) {
      rails.push({ a, b });
      if (!run) { run = [[a[0], a[1] + RAIL_HEIGHT, a[2]]]; railTops.push(run); }
      run.push([b[0], b[1] + RAIL_HEIGHT, b[2]]);
      continue;
    }
    run = null;
    if (inOpen(mx, mz, 'ground')) { // abutment wall under a landing edge
      const o = D.open.find(q => Math.hypot(mx - q.x, mz - q.z) < q.r)!, base = (o.ground ?? a[1] - 3) - 1.5;
      if (a[1] - slab > base + .2) st.quad([a[0], a[1] - slab, a[2]], [b[0], b[1] - slab, b[2]], [b[0], base, b[2]], [a[0], base, a[2]], C.concrete);
    }
  }

  // ---- helix: 3 radial strips (band / centre / band), soffit, fascia girders, railings, columns in the garden
  const nSeg = Math.ceil((H.phiTop - H.phiEnd) / HELIX_STEP);
  const radii = [H.rIn, H.rIn + D.band * .75, H.rOut - D.band * .75, H.rOut];
  const hp = (phi: number, r: number, dy = 0): V3 => { const t = phi * Math.PI / 180; return [H.c[0] + Math.cos(t) * r, helixY(phi) + dy, H.c[1] + Math.sin(t) * r]; };
  for (let k = 0; k < nSeg; k++) {
    const p0 = H.phiTop - (H.phiTop - H.phiEnd) * k / nSeg, p1 = H.phiTop - (H.phiTop - H.phiEnd) * (k + 1) / nSeg;
    for (let s = 0; s < 3; s++) {
      const c = s === 1 ? C.centre : C.band, [r0, r1] = [radii[s], radii[s + 1]];
      deck.tri(hp(p0, r0), hp(p1, r0), hp(p1, r1), c, true); deck.tri(hp(p0, r0), hp(p1, r1), hp(p0, r1), c, true);
    }
    st.quad(hp(p0, H.rIn, -slab), hp(p1, H.rIn, -slab), hp(p1, H.rOut, -slab), hp(p0, H.rOut, -slab), C.soffit);
    for (const r of [H.rIn, H.rOut]) {
      st.quad(hp(p0, r, .04), hp(p1, r, .04), hp(p1, r, -slab), hp(p0, r, -slab), C.concrete);
      st.quad(hp(p0, r, -slab), hp(p1, r, -slab), hp(p1, r, -slab - .55), hp(p0, r, -slab - .55), C.steel);
      const a = hp(p0, r), b = hp(p1, r), mx = (a[0] + b[0]) / 2, mz = (a[2] + b[2]) / 2;
      // Upper-turn outer edge joins the main deck inside the helix junction zone: open there.
      if (!(r === H.rOut && p0 > H.phiTop - 60 && inOpen(mx, mz, 'helix'))) rails.push({ a, b });
    }
  }
  rails.push({ a: hp(H.phiTop, H.rIn), b: hp(H.phiTop, H.rOut) }); // top end: a drop to the turn below
  st.quad(hp(H.phiTop, H.rIn, .04), hp(H.phiTop, H.rOut, .04), hp(H.phiTop, H.rOut, -slab - .55), hp(H.phiTop, H.rIn, -slab - .55), C.concrete);
  let helixColumns = 0;
  for (let t = 0; t < 360; t += 45) {
    const levels: number[] = [];
    for (let phi = t + 720; phi >= t - 1080; phi -= 360) if (phi <= H.phiTop && phi >= H.phiEnd) levels.push(helixY(phi));
    if (!levels.length) continue;
    const top = Math.max(...levels) - slab - .1, rr = H.rIn - .55, a = t * Math.PI / 180;
    const cx = H.c[0] + Math.cos(a) * rr, cz = H.c[1] + Math.sin(a) * rr;
    deck.prism(cx, cz, .32, .32, H.yEnd - 1.2, top, 8, C.concrete, true);
    for (const y of levels) deck.box(H.c[0] + Math.cos(a) * (H.rIn - .3), H.c[1] + Math.sin(a) * (H.rIn - .3), [Math.cos(a), Math.sin(a)], .32, .25, y - slab - .5, y - slab, C.concrete);
    helixColumns++;
  }

  // ---- girders: curved weathering-steel plate girders (web + bottom flange) under the main deck
  let girderLengthM = 0;
  for (const g of D.girders) for (let i = 0; i + 1 < g.length; i++) {
    const a = g[i], b = g[i + 1], ya = a[1] - slab, yb = b[1] - slab;
    girderLengthM += Math.hypot(b[0] - a[0], b[2] - a[2]);
    st.quad([a[0], ya, a[2]], [b[0], yb, b[2]], [b[0], yb - GIRDER_DEPTH, b[2]], [a[0], ya - GIRDER_DEPTH, a[2]], C.steel);
    const dx = b[0] - a[0], dz = b[2] - a[2], l = Math.hypot(dx, dz) || 1, nx = -dz / l * .24, nz = dx / l * .24;
    st.quad([a[0] - nx, ya - GIRDER_DEPTH, a[2] - nz], [b[0] - nx, yb - GIRDER_DEPTH, b[2] - nz], [b[0] + nx, yb - GIRDER_DEPTH, b[2] + nz], [a[0] + nx, ya - GIRDER_DEPTH, a[2] + nz], C.steel);
  }

  // ---- piers: curved twin-column concrete bents (columns flare into the cap, arched opening between them)
  for (const p of D.piers) {
    const target = p.water ? st : deck;
    const top = p.deck - slab - GIRDER_DEPTH, capH = 1.1, capBot = top - capH, Hh = Math.max(2.2, p.half - .5);
    const ub = Math.max(1.3, Hh * .5), N = 8, prof: [number, number][] = [];
    const uo = (t: number) => ub + (Hh * .92 - ub) * Math.pow(t, 2.2), ui = (t: number) => (ub - 1.05) * (1 - Math.pow(t, 1.7));
    const yAt = (t: number) => p.base + (capBot - p.base) * t;
    for (let k = 0; k <= N; k++) prof.push([-uo(k / N), yAt(k / N)]);
    prof.push([-Hh, capBot], [-Hh, top], [Hh, top], [Hh, capBot]);
    for (let k = N; k >= 0; k--) prof.push([uo(k / N), yAt(k / N)]);
    for (let k = 0; k < N; k++) prof.push([ui(k / N), yAt(k / N)]);
    prof.push([0, yAt(1) - .05]);
    for (let k = N - 1; k >= 0; k--) prof.push([-ui(k / N), yAt(k / N)]);
    const [ux, uz] = p.dir, tx = -uz * .75, tz = ux * .75;
    const W = (u: number, y: number, s: number): V3 => [p.x + ux * u + tx * s, y, p.z + uz * u + tz * s];
    const tris = THREE.ShapeUtils.triangulateShape(prof.map(([u, y]) => new THREE.Vector2(u, y)), []);
    for (const s of [-1, 1]) for (const t of tris) target.tri(W(prof[t[0]][0], prof[t[0]][1], s), W(prof[t[1]][0], prof[t[1]][1], s), W(prof[t[2]][0], prof[t[2]][1], s), C.concrete);
    for (let i = 0; i < prof.length; i++) {
      const a = prof[i], b = prof[(i + 1) % prof.length];
      target.quad(W(a[0], a[1], -1), W(b[0], b[1], -1), W(b[0], b[1], 1), W(a[0], a[1], 1), C.concrete);
    }
    if (p.water) st.box(p.x, p.z, [ux, uz], ub + .5, 1.3, D.waterY - 1, D.waterY + .45, C.soffit); // footing at the waterline
  }

  // ---- railings: posts, top/bottom rails, mesh infill panels; lamps and planters along the main deck edges
  let railLengthM = 0, lamps = 0, planters = 0, sinceLamp = LAMP_SPACING / 2, sincePost = 0, lampIndex = 0;
  const railPos: number[] = [], railIdx: number[] = [];
  for (const { a, b } of rails) {
    const dx = b[0] - a[0], dz = b[2] - a[2], len = Math.hypot(dx, dz);
    if (len < 1e-3) continue;
    const ux = dx / len, uz = dz / len;
    const mx = (a[0] + b[0]) / 2, mz = (a[2] + b[2]) / 2, onMain = Math.hypot(mx - H.c[0], mz - H.c[1]) > H.rOut + .2;
    // inward normal (towards the deck)
    let nx = -uz, nz = ux;
    if (onMain ? !inDeck(mx + nx * .5, mz + nz * .5) : Math.abs(Math.hypot(mx + nx * .5 - H.c[0], mz + nz * .5 - H.c[1]) - (H.rIn + H.rOut) / 2) > Math.abs(Math.hypot(mx - nx * .5 - H.c[0], mz - nz * .5 - H.c[1]) - (H.rIn + H.rOut) / 2)) { nx = -nx; nz = -nz; }
    const off = .12, A: V3 = [a[0] + nx * off, a[1], a[2] + nz * off], B: V3 = [b[0] + nx * off, b[1], b[2] + nz * off];
    const at = (s: number, dy: number): V3 => [A[0] + (B[0] - A[0]) * s, A[1] + (B[1] - A[1]) * s + dy, A[2] + (B[2] - A[2]) * s];
    // rails: top rail (box-ish), bottom rail ribbon
    st.quad(at(0, RAIL_HEIGHT), at(1, RAIL_HEIGHT), at(1, RAIL_HEIGHT - .07), at(0, RAIL_HEIGHT - .07), C.rail);
    st.quad([A[0] - nx * .04, A[1] + RAIL_HEIGHT, A[2] - nz * .04], [B[0] - nx * .04, B[1] + RAIL_HEIGHT, B[2] - nz * .04], [B[0] + nx * .04, B[1] + RAIL_HEIGHT, B[2] + nz * .04], [A[0] + nx * .04, A[1] + RAIL_HEIGHT, A[2] + nz * .04], C.rail);
    st.quad(at(0, .16), at(1, .16), at(1, .1), at(0, .1), C.rail);
    st.quad(at(0, RAIL_HEIGHT * .55), at(1, RAIL_HEIGHT * .55), at(1, RAIL_HEIGHT * .55 - .04), at(0, RAIL_HEIGHT * .55 - .04), C.rail);
    mesh.quad(at(0, .16), at(1, .16), at(1, RAIL_HEIGHT - .07), at(0, RAIL_HEIGHT - .07), C.rail);
    meshUv.push(railLengthM, 0, railLengthM + len, 0, railLengthM + len, 1, railLengthM, 0, railLengthM + len, 1, railLengthM, 1);
    // collider quad
    const v0 = railPos.length / 3;
    railPos.push(A[0], A[1] - .2, A[2], B[0], B[1] - .2, B[2], B[0], B[1] + RAIL_HEIGHT, B[2], A[0], A[1] + RAIL_HEIGHT, A[2]);
    railIdx.push(v0, v0 + 1, v0 + 2, v0, v0 + 2, v0 + 3);
    // posts
    for (let s = (POST_SPACING - sincePost); s < len; s += POST_SPACING) {
      const p = at(s / len, 0);
      st.box(p[0], p[2], [ux, uz], .055, .055, p[1], p[1] + RAIL_HEIGHT + .06, C.rail);
      st.prism(p[0], p[2], .08, 0, p[1] + RAIL_HEIGHT + .06, p[1] + RAIL_HEIGHT + .16, 4, C.rail);
    }
    sincePost = (sincePost + len) % POST_SPACING;
    // lamps (main deck only) and planters on the wide plaza
    if (onMain) {
      for (let s = LAMP_SPACING - sinceLamp; s < len; s += LAMP_SPACING) {
        const q = at(s / len, 0), lx = q[0] + nx * .35, lz = q[2] + nz * .35, y = q[1];
        if (!inDeck(lx, lz) || inOpen(lx, lz)) continue;
        st.box(lx, lz, [ux, uz], .26, .26, y, y + 1.15, C.lamp);
        st.prism(lx, lz, .1, .08, y + 1.15, y + 5.6, 6, C.lamp);
        st.prism(lx, lz, .16, .16, y + 5.6, y + 6.0, 6, C.glass);
        st.prism(lx, lz, .6, .08, y + 6.0, y + 6.12, 8, C.lamp, true);
        st.prism(lx, lz, .45, .06, y + 6.32, y + 6.42, 8, C.lamp, true);
        st.prism(lx, lz, .06, .02, y + 6.42, y + 6.75, 4, C.lamp);
        lamps++;
        // Planter beds between lamps where the deck is a plaza (> 10 m across).
        if (lampIndex++ % 2 === 0) {
          let w = 0;
          while (w < 16 && inDeck(q[0] + nx * (w + .5), q[2] + nz * (w + .5))) w += .5;
          const px = q[0] + nx * 1.1 + ux * 4, pz = q[2] + nz * 1.1 + uz * 4;
          if (w > 10 && inDeck(px + nx * .8, pz + nz * .8) && !inOpen(px, pz)) {
            st.box(px, pz, [ux, uz], 1.5, .7, y - .05, y + .7, C.concrete, false);
            st.quad([px - ux * 1.45 - nx * .65, y + .62, pz - uz * 1.45 - nz * .65], [px + ux * 1.45 - nx * .65, y + .62, pz + uz * 1.45 - nz * .65],
              [px + ux * 1.45 + nx * .65, y + .62, pz + uz * 1.45 + nz * .65], [px - ux * 1.45 + nx * .65, y + .62, pz - uz * 1.45 + nz * .65], C.soil);
            for (let k = -1; k <= 1; k++) st.prism(px + ux * k * .9, pz + uz * k * .9, .5, .1, y + .62, y + 1.35, 5, C.plant);
            planters++;
          }
        }
      }
      sinceLamp = (sinceLamp + len) % LAMP_SPACING;
    }
    railLengthM += len;
  }

  const deckGeo = deck.geometry();
  const position = deckGeo.getAttribute('position').array as Float32Array;
  return {
    deck: deckGeo, deckCollider: { position, index: Uint32Array.from({ length: position.length / 3 }, (_, i) => i) },
    structure: st.geometry(), infill: mesh.geometry(meshUv.map((v, i) => i % 2 ? v : v / (INFILL_PITCH * INFILL_WIRES_PER_TEXTURE))),
    railCollider: { position: new Float32Array(railPos), index: new Uint32Array(railIdx) }, railTops,
    stats: { deckTriangles: deck.triangles, structureTriangles: st.triangles, infillTriangles: mesh.triangles, railSegments: railIdx.length / 6,
      railLengthM: +railLengthM.toFixed(1), lamps, planters, piers: D.piers.length, helixColumns, girderLengthM: +girderLengthM.toFixed(1),
      helixTurns: +((H.phiTop - H.phiEnd) / 360).toFixed(2) },
  };
}

/** Infill pitch: one vertical mesh wire every 0.1 m; the procedural alpha texture holds 8 wires across 64 texels. */
export const INFILL_PITCH = .1, INFILL_WIRES_PER_TEXTURE = 8;
/** Beyond this camera distance band the infill fades to a uniform semi-opaque grey (no moire at mid range). */
export const INFILL_FADE: [number, number, number] = [22, 38, .42];

/** Materials: one vertex-coloured standard material (deck + structure) and the mesh infill (procedural alpha:
 * 64x8 power-of-two texture, mipmapped trilinear so the chain averages to partial alpha; a view-distance fade turns the
 * panel into a uniform 42 % grey beyond ~38 m). No external textures. */
export function createPflugerMaterials() {
  const solid = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: .82, metalness: .05, side: THREE.DoubleSide });
  solid.name = 'Pfluger bridge (vertex colours)';
  const W = 64, Hh = 8, texels = new Uint8Array(W * Hh * 4), per = W / INFILL_WIRES_PER_TEXTURE;
  for (let j = 0; j < Hh; j++) for (let i = 0; i < W; i++) {
    const v = i % per < 3 ? 255 : 0; // 3 of every 8 texels: a wire (37.5 % coverage)
    texels.set([v, v, v, 255], (j * W + i) * 4);
  }
  const alpha = new THREE.DataTexture(texels, W, Hh, THREE.RGBAFormat);
  alpha.wrapS = alpha.wrapT = THREE.RepeatWrapping;
  alpha.magFilter = THREE.LinearFilter; alpha.minFilter = THREE.LinearMipmapLinearFilter; alpha.generateMipmaps = true; alpha.anisotropy = 4;
  alpha.needsUpdate = true;
  const infill = new THREE.MeshStandardMaterial({ color: PFLUGER_COLORS.rail, roughness: .6, metalness: .4, alphaMap: alpha, transparent: true,
    alphaTest: .02, depthWrite: true, side: THREE.DoubleSide });
  infill.name = 'Pfluger railing mesh infill';
  const [near, far, a] = INFILL_FADE;
  infill.onBeforeCompile = shader => {
    shader.fragmentShader = shader.fragmentShader.replace('#include <alphamap_fragment>',
      `#include <alphamap_fragment>\n\tfloat pfFade = smoothstep( ${near.toFixed(1)}, ${far.toFixed(1)}, length( vViewPosition ) );\n\tdiffuseColor.a = mix( diffuseColor.a, ${a.toFixed(2)}, pfFade );`);
  };
  infill.customProgramCacheKey = () => 'pfluger-infill-fade-v1';
  return { solid, infill, textures: [alpha] };
}
